use crate::domains::kernel_opt::corpus::KernelRule;

/// Data table, not logic -- grows with distillation batches.
#[allow(clippy::too_many_lines)]
pub(super) fn entries() -> Vec<KernelRule> {
    vec![
        // ── N: the ACTIVATION-side offset elimination — emit SIGNED codes
        // and the dequant epilogue's folded-offset term (and its loads)
        // disappear. The writer-side mirror of B180's weight-side
        // deferred-bias rule. ──────────────────────────────────────────
        // Source: Qwen35.swift (the signed-codes doc + the signedCodes
        // probe; kill-switch DARKBLOOM_BONSAI_TENSOR_ROUTE_SIGNED).
        KernelRule {
            rule_id: "signed-activation-codes-drop-dequant-offset-term".to_string(),
            gpu_concept: "MECHANISM (activation-side offset ELIMINATION at the writer): emit the quantized activation codes SIGNED (q) instead of unsigned (q + 128), so the group dot carries no +128*colsum offset and the dequant epilogue's folded-offset correction term -- and its loads -- disappear outright. SOURCE-REPORTED (Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d, Qwen35.swift, verbatim): 'The int8-staged prompt kernel reads the activation codes as signed int8 (`q`, not `q + 128`): its products then carry no `128 * colsum` offset, so the epilogue's folded-offset term and its two 16-byte loads per lane and group go away. Same values bit for bit: `fma(s, C, -128 s colsum)` and `s * (C - 128 colsum)` each round once to the same number (the offset is exact in FP32). Only that form takes it; the native and 4-bit-staged forms keep the unsigned codes.' Kill-switch DARKBLOOM_BONSAI_TENSOR_ROUTE_SIGNED=0. REGIME 1 (mantissa budget -- BOTH clauses are the rule): the rewrite is exact only while bits(scale) + bits(colsum) <= 24 (the FP32 significand) -- 2-bit weights group-128: colsum <= 384 (9 bits) + FP16 scale (11 bits) = 20 bits, exact; 4-bit: ~22 bits, exact; 8-bit: colsum to 32,640 (15 bits) -> 26 bits, NOT exact in general; an FP32 scale breaks the budget earlier. Upstream's own scope is a kernel-form restriction (staged8 only), NARROWER than the precision bound -- do not read its exclusion of the 4-bit-staged form as a precision verdict. REGIME 2 (consumer ISA): the q+128 offset usually exists BECAUSE the consumer dot wants UNSIGNED activations -- x86 VNNI vpdpbusd / AVX2 vpmaddubsw are u8xs8, so there the offset is FORCED and signed codes win nothing. Pays only under WRITER CONTROL with a consumer dot that accepts signed activations: CUDA dp4a, NEON sdot, Metal staged-int8 MMA. ANTI-REGIME: no writer control, a u8xs8-only consumer ISA, or codes/scales exceeding the 24-bit mantissa budget -- keep unsigned codes + the folded-offset epilogue (a NEGATIVE fixture arm outside the regime is mandatory, the equality genuinely breaks). FAMILY (offset handling, do not double-count): B107 integer-mma-span-epilogue-dequant = consumer precomputed per-group code-sum LOOKUP; B96 bit-plane-plane-sums-input-side-offset-dot = consumer bit-plane offset dot; B180 deferred-bias-ternary-dp4a-exact-isum = weight-side deferred-bias dp4a, the MIRROR IMAGE (Batch 180 / Plan 173 -- cross-referenced, landed separately); THIS rule = activation-side writer ELIMINATION -- signed codes make the correction term identically ZERO: no lookup, no loads, no deferred add. ENABLER (the record, not polish): the arena's verify route runs int8 x int8 -> int32 tensor ops 'at the int8 rate of the tensor unit (about twice the FP16 rate)' -- SOURCE-REPORTED 116 vs 58 TF/s on an M5 Max; signed codes are what make that route clean (the enabler of the arena record, not a polish commit). ANSWER SHAPE: three-form dispatch staged8|native2b|none (kill-switch DARKBLOOM_BONSAI_TENSOR_ROUTE_VERIFY_FORM) -- probe the ISA, pick the fastest LEGAL operand form, keep fallbacks. CITE: Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d -- Vendor/mlx-swift-lm/Libraries/MLXLLM/Models/Qwen35.swift (the signed-codes doc + signedCodes probe). Batch 181 / Plan 174 / Research 212.".to_string(),
            ref_shape: "const GROUP: usize = 128;\n\n// The writer emits UNSIGNED codes (q + 128); a per-group colsum table\n// is materialized beside the scales so the epilogue can undo the offset.\nstruct GroupTables {\n    scales: Vec<f32>,\n    colsums: Vec<f32>,\n}\n\nfn colsum(codes: &[i8]) -> i32 {\n    codes.iter().map(|&c| c as i32).sum()\n}\n\n// NAIVE: unsigned activation codes dotted against signed weight codes;\n// the dot carries a +128*colsum offset the epilogue must subtract.\nfn group_dot_unsigned(codes: &[i8], acts: &[i8], g: usize, t: &GroupTables) -> f32 {\n    let base = g * GROUP;\n    let mut c: i32 = 0;\n    for k in 0..GROUP {\n        c += codes[base + k] as i32 * acts[base + k] as i32;\n    }\n    let s = t.scales[g]; // load 1: the group scale\n    let cs = t.colsums[g]; // load 2: the group code-sum (the offset's size)\n    // folded-offset epilogue: fma(s, C, -128 s colsum)\n    s.mul_add(c as f32, -128.0 * s * cs)\n}\n\npub fn prompt_proj_unsigned(codes: &[i8], acts: &[i8], groups: usize, t: &GroupTables) -> Vec<f32> {\n    (0..groups).map(|g| group_dot_unsigned(codes, acts, g, t)).collect()\n}".to_string(),
            opt_pattern: "const GROUP: usize = 128;\n\n// The writer emits SIGNED codes; the colsum table no longer exists.\nstruct GroupScales {\n    scales: Vec<f32>,\n}\n\n// OPT: signed activation codes; the dot IS the exact integer the\n// epilogue wants -- the offset term and its second load are gone.\n// REGIME: writer control AND a signed-activation consumer dot\n// (dp4a / sdot / staged-int8 MMA); the u8xs8 lanes keep unsigned.\nfn group_dot_signed(codes: &[i8], acts: &[i8], g: usize, t: &GroupScales) -> f32 {\n    let base = g * GROUP;\n    let mut c: i32 = 0;\n    for k in 0..GROUP {\n        c += codes[base + k] as i32 * acts[base + k] as i32;\n    }\n    t.scales[g] * c as f32 // one load, zero correction arithmetic\n}\n\npub fn prompt_proj_signed(codes: &[i8], acts: &[i8], groups: usize, t: &GroupScales) -> Vec<f32> {\n    (0..groups).map(|g| group_dot_signed(codes, acts, g, t)).collect()\n}\n\n// Three-form dispatch: probe the consumer ISA, pick the fastest LEGAL\n// operand form, keep the fallbacks (the source's answer shape).\n#[derive(Clone, Copy, PartialEq, Eq)]\nenum VerifyForm {\n    Staged8,  // int8 x int8 -> int32 tensor ops over signed codes\n    Native2b, // native 2-bit weight path, unsigned codes kept\n    None,     // composed fallback\n}\n\nfn pick_form(writer_control: bool, signed_tensor_dot: bool) -> VerifyForm {\n    if writer_control && signed_tensor_dot {\n        VerifyForm::Staged8\n    } else if signed_tensor_dot {\n        VerifyForm::Native2b\n    } else {\n        VerifyForm::None\n    }\n}".to_string(),
        },

        // ── C: the WRITER-layer fusion — the transform is fused INTO the
        // quantize writer so it never exists as a separate pass, with a
        // construction-time bit-check gate and fail-open fallback. ─────
        // Source: Hadamard.swift (SignedBlockHadamard writer surface) +
        // Qwen35.swift (Qwen35FusedBoundaryQ8 / Qwen35FusedHadamard /
        // Qwen35AttentionPreworkExplicit).
        KernelRule {
            rule_id: "fused-transform-quantize-writer".to_string(),
            gpu_concept: "MECHANISM (writer-layer fusion): fuse the activation-side transform INTO the quantize writer -- ONE kernel emits codes + scales + scaled sums directly, so the transform never exists as a separate pass over a materialized intermediate. SOURCE-REPORTED (Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d): SignedBlockHadamard.forwardInt8 / forwardWithGroupSums is one kernel emitting codes+scales+scaledSums; the same fusion is carried INTO the activation functions themselves -- rotatedSwiGLU / rotatedSigmoidGate / rotatedGatedRMSNorm -- and applyPreSigned carries presigned codes through producers; Qwen35FusedBoundaryQ8 fuses RMSNorm + quantize into ONE kernel writing normed output + codes + scales + sums; Qwen35FusedHadamard fuses activation transform + quantize with the staged8 permutation; Qwen35AttentionPreworkExplicit does q/k norm + transpose + rope in ONE launch. APPLICABILITY-WIDENING (the transferable technique): 'the rotation reads the chain's own cosine/sine tables instead of deriving angles from a scalar offset, so it applies wherever Qwen35MRoPE.apply applies, with no consecutiveness assumption' -- consume the FALLBACK's own intermediate tables instead of re-deriving them, and the fused form inherits the fallback's exact input domain. MANDATORY GATE (construction-time bit-check): 'one geometry is compiled and checked bit for bit at model construction, on the box that runs it, before any timed forward'; any mismatch (or backend error) KEEPS the composed path -- fail-open behind kill-switch BONSAI_FUSED_BOUNDARY_Q8=0. A fused writer is adopted per-box by proof at load, never by claim. RIDER (cast hazard, the 6.1 shortlist defect): the packed layer type IS-A QuantizedLinear (HadamardQuantizedLinear subclasses it), so a raw .weight read through the base type succeeds silently and SKIPS the fused transform -- the fusion is only safe behind the layer's own forward; downstream code must never bypass the writer type. RIDER (strided zero-copy): HadamardStridedInputs reads [B,S,heads,headDim] operands IN PLACE through strides -- 'the head-transposed attention output and the gate half of each q|gate head are not reshaped into copies first. Same elements, same arithmetic.' KINSHIPS / DISTINCT-FROM: the FWHT ladder family (fwht-wide-block-row-per-threadgroup-exchange-ladder, B116; the #29094/#29095 upstream instances) transforms WEIGHTS/blocks -- the FFT-exchange mechanics layer; THIS fuses the ACTIVATION transform into the quantize writer -- the writer layer; COMPOSE, do not duplicate (the fused writer calls the same transform the ladder optimizes). Dedup-checked against fixed-ref-softmax-decode-walk (B170) -- different mechanism, clean. ANTI-REGIME: no writer control over the producing op; transform outputs consumed by MORE than the quantize path (materialization would pay double); an environment where the load-time bit-check cannot run -- keep the composed transform-pass + quantize-pass pair. CITE: Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d -- Vendor/mlx-swift/Source/MLXNN/Hadamard.swift (the SignedBlockHadamard writer surface) + Vendor/mlx-swift-lm/Libraries/MLXLLM/Models/Qwen35.swift (FusedBoundaryQ8 / FusedHadamard / AttentionPreworkExplicit). Batch 181 / Plan 174 / Research 212. RIDER (Batch 182, the same delta's post-pin accept wave, delta cfb35b0d..831fae7): the family WIDENS at the verify width and gains instances -- (a) `tensorRouteNarrowForwardProducer` folds the PRODUCER (SwiGLU / sigmoidGate / gatedRMSNorm) into the quantizing rotation's read for full 16-row verify windows ('the quantizing rotation forms the producer in its read instead of a separate elementwise launch storing the signed product first'), gated BONSAI_NARROW_PRODUCER with a LOAD-TIME ROUND-TRIAL ADOPTION (adopt only when its rounds measure faster -- the whole-round-in-situ-adoption-trial B182 shape as the adoption gate); (b) `fusedInverse` (transform + sign-multiply as ONE installed kernel, nil declines); (c) `tensorPackedMatmulHead` (the vocab-head kernel at verify width, FP32 logits without the core's FP16 rounding); (d) `leadingRows(_:)` (a cached module-slice view computing only a frequency-ranked vocabulary prefix for drafter scoring -- no full-head read); (e) the zero-copy class instance 2 at the query-block seam: the prompt attention's four [1,24,128,256] FP32 block outputs are no longer CONCATENATED per layer just so the o_proj producer rotation can read them through head-transposed strides -- the rotation takes the blocks as separate inputs and computes the concatenated-row address ('everything after the read is the q8pv text, so every output has the same bits', BONSAI_ATTN_BLOCKS_INPLACE=0, Qwen35.swift L7953-7957); all the same fold-the-pass-into-one-kernel family, default-off/decline-nil posture identical to the parent rule.".to_string(),
            ref_shape: "const BLK: usize = 4; // transform block == quant group in this fixture\n\nfn hadamard4(b: &mut [f32; BLK]) {\n    let (a, c, d, e) = (b[0], b[1], b[2], b[3]);\n    b[0] = a + c + d + e;\n    b[1] = a - c + d - e;\n    b[2] = a + c - d - e;\n    b[3] = a - c - d + e;\n}\n\n// NAIVE pass 1: the transform exists as its own pass, materializing a\n// full transformed-activation buffer.\nfn transform_pass(acts: &[f32]) -> Vec<f32> {\n    let mut out = acts.to_vec();\n    for chunk in out.chunks_mut(BLK) {\n        let mut b = [0.0f32; BLK];\n        b.copy_from_slice(chunk);\n        hadamard4(&mut b);\n        chunk.copy_from_slice(&b);\n    }\n    out\n}\n\n// NAIVE pass 2: a separate quantize writer re-reads the buffer.\nfn quantize_pass(t: &[f32]) -> (Vec<i8>, Vec<f32>, Vec<f32>) {\n    let mut codes = Vec::with_capacity(t.len());\n    let mut scales = Vec::new();\n    let mut sums = Vec::new();\n    for grp in t.chunks(BLK) {\n        let m = grp.iter().fold(0.0f32, |acc, &v| acc.max(v.abs()));\n        let s = if m == 0.0 { 1.0 } else { m / 127.0 };\n        let mut sum = 0.0f32;\n        for &v in grp {\n            let q = (v / s).round() as i8;\n            codes.push(q);\n            sum += q as f32;\n        }\n        scales.push(s);\n        sums.push(s * sum); // scaled sums\n    }\n    (codes, scales, sums)\n}\n\npub fn naive_pipeline(acts: &[f32]) -> (Vec<i8>, Vec<f32>, Vec<f32>) {\n    let t = transform_pass(acts);\n    quantize_pass(&t)\n}".to_string(),
            opt_pattern: "const BLK: usize = 4;\n\nfn hadamard4(b: &mut [f32; BLK]) {\n    let (a, c, d, e) = (b[0], b[1], b[2], b[3]);\n    b[0] = a + c + d + e;\n    b[1] = a - c + d - e;\n    b[2] = a + c - d - e;\n    b[3] = a - c - d + e;\n}\n\n// The composed (fallback) pipeline, kept verbatim.\nfn composed(acts: &[f32]) -> (Vec<i8>, Vec<f32>, Vec<f32>) {\n    let mut t = acts.to_vec();\n    for chunk in t.chunks_mut(BLK) {\n        let mut b = [0.0f32; BLK];\n        b.copy_from_slice(chunk);\n        hadamard4(&mut b);\n        chunk.copy_from_slice(&b);\n    }\n    let mut codes = Vec::with_capacity(t.len());\n    let mut scales = Vec::new();\n    let mut sums = Vec::new();\n    for grp in t.chunks(BLK) {\n        let m = grp.iter().fold(0.0f32, |acc, &v| acc.max(v.abs()));\n        let s = if m == 0.0 { 1.0 } else { m / 127.0 };\n        let mut sum = 0.0f32;\n        for &v in grp {\n            let q = (v / s).round() as i8;\n            codes.push(q);\n            sum += q as f32;\n        }\n        scales.push(s);\n        sums.push(s * sum);\n    }\n    (codes, scales, sums)\n}\n\n// FUSED: ONE writer runs the transform inside the quantize loop; no\n// transformed-activation buffer is ever materialized.\nfn fused_writer(acts: &[f32]) -> (Vec<i8>, Vec<f32>, Vec<f32>) {\n    let mut codes = Vec::with_capacity(acts.len());\n    let mut scales = Vec::new();\n    let mut sums = Vec::new();\n    let mut b = [0.0f32; BLK];\n    for chunk in acts.chunks(BLK) {\n        b.copy_from_slice(chunk);\n        hadamard4(&mut b); // the transform INSIDE the writer\n        let m = b.iter().fold(0.0f32, |acc, &v| acc.max(v.abs()));\n        let s = if m == 0.0 { 1.0 } else { m / 127.0 };\n        let mut sum = 0.0f32;\n        for &v in b.iter() {\n            let q = (v / s).round() as i8;\n            codes.push(q);\n            sum += q as f32;\n        }\n        scales.push(s);\n        sums.push(s * sum);\n    }\n    (codes, scales, sums)\n}\n\n#[derive(Clone, Copy, PartialEq, Eq)]\nenum BoundaryForm {\n    Fused,\n    Composed,\n}\n\n// Construction-time gate: check the fused geometry bit for bit ON THIS\n// BOX before any timed forward. Fail-open: any mismatch (or the\n// kill-switch) keeps the composed path.\nfn pick_boundary(acts: &[f32], kill_switch: bool) -> BoundaryForm {\n    if kill_switch {\n        return BoundaryForm::Composed;\n    }\n    let fused = fused_writer(acts);\n    let composed_out = composed(acts);\n    if fused == composed_out {\n        BoundaryForm::Fused\n    } else {\n        BoundaryForm::Composed\n    }\n}".to_string(),
        },

        // ── B: tensor-unit MMA over staged quantized codes, the weight
        // tile staged per-simdgroup and double-buffered; the drafter's
        // BF16 block projections are the second instance. ──────────────
        // Source: Qwen35.swift (Qwen35TensorPackedMatmul) + DFlash2Draft.swift
        // (DFlash2TensorMatmul + the STACK_GATEUP rider).
        KernelRule {
            rule_id: "tensor-core-mma-staged-quantized-codes-double-buffered".to_string(),
            gpu_concept: "MECHANISM: block-quantized / narrow-dtype matmuls become TENSOR-UNIT MMA work when the weight slice is staged per-threadgroup in the operand width the tensor unit eats, with the staging ring double-buffered so the next K-group's stage is built while the op consumes the current one. SOURCE-REPORTED (Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d) -- TWO instances: (a) the int8-codes prompt kernel Qwen35TensorPackedMatmul runs matmul2d over descriptors 64,64,128 (prompt, 4-simdgroup execution) and 16,TN,128 (verify width, single simdgroup) with cooperative-tensor destinations, staging the weight tile as int8/uint8 in per-simdgroup threadgroup buffers with a B0/B1 ring (the next K-group staged into cur^1 before the op on cur); the verify route's int8 x int8 -> int32 ops run 'at the int8 rate of the tensor unit (about twice the FP16 rate)' -- 116 vs 58 TF/s on an M5 Max; (b) the DRAFTER's BF16 block projections DFlash2TensorMatmul: matmul2d_descriptor(16, 32, 256, mode::multiply_accumulate), K-quarters per simdgroup with partials 'summed through threadgroup memory'; 'The result is the same FP32-accumulated product in a different summation order, rounded to BF16. The drafter only proposes.' (kill-switch DARKBLOOM_DFLASH2_TENSOR_MATMUL=0) -- instance (b) is lane-relevant to the riir-ai Issue-846 chat row (the drafter's own cost). RIDER (weight-stack family, DARKBLOOM_DFLASH2_STACK_GATEUP): stack gate+up along the output axis ONCE on first use -- 'the same BF16 bytes as the two loaded weights, concatenated once on first use and held in a plain class (never a stored MLXArray on the module, so reflection cannot add it to the parameter tree)'; 'One matmul over the stack replaces two over the same input, and the block's 16 rows fill one wider tensor tile instead of two.' REGIME: block-quantized or narrow-dtype matmuls on silicon whose tensor unit eats that operand width; the weight slice is RE-READ across the K loop (staging pays); the K loop allows one stage of lookahead (double-buffering pays). ANTI-REGIME: GEMV decode shapes (no tensor unit), weight slices bigger than threadgroup memory per stage, single-use slices (staging is a copy for nothing). CITE: Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d -- Vendor/mlx-swift-lm/Libraries/MLXLLM/Models/Qwen35.swift + DFlash2Draft.swift. Batch 181 / Plan 174 / Research 212.".to_string(),
            ref_shape: "// Naive: per-output-column dot over packed 2-bit weights,\n// dequantizing per-group INSIDE the inner loop against a single\n// weight buffer -- no staging, no tensor-unit operand form.\nconst CODES_PER_BYTE: usize = 4;\nconst GROUP: usize = 8;\n\npub struct PackedWeights {\n    pub codes: Vec<u8>,   // 2-bit codes, 4 per byte\n    pub scales: Vec<f32>, // one scale per GROUP codes\n}\n\npub fn dequant_dot_naive(x: &[f32], w: &PackedWeights, col: usize, k: usize) -> f32 {\n    let mut acc = 0.0f32;\n    for kk in 0..k {\n        let idx = col * k + kk;\n        let byte = w.codes[idx / CODES_PER_BYTE];\n        let shift = (idx % CODES_PER_BYTE) * 2;\n        let code = (byte >> shift) & 0x3;\n        let qw = (code as i32 - 1) as f32 * w.scales[idx / GROUP];\n        acc += x[kk] * qw; // dequant in the inner loop, every use\n    }\n    acc\n}".to_string(),
            opt_pattern: "// Optimized: stage one K-tile of the weight slice ONCE (the\n// per-threadgroup staging tile, simulated here as a local array) with a\n// B0/B1 double buffer -- the NEXT group's stage is built into\n// buf[(g + 1) % 2] before the op consumes buf[g % 2]. Plus the gate+up\n// stack rider: the two weight slices are concatenated ONCE on first use\n// into a plain value held OUTSIDE the parameter tree, and ONE matmul\n// runs over the stack (16 block rows fill one wider tile).\nconst TILE: usize = 128;\nconst CODES_PER_BYTE: usize = 4;\nconst GROUP: usize = 8;\n\npub struct PackedWeights {\n    pub codes: Vec<u8>,\n    pub scales: Vec<f32>,\n}\n\n// Build the NEXT K-tile's stage: decode TILE codes once per stage\n// instead of per use in the inner loop.\nfn stage_tile(w: &PackedWeights, dst: &mut [f32; TILE], col: usize, tile_g: usize, k: usize) {\n    for i in 0..TILE {\n        let idx = col * k + tile_g * TILE + i;\n        let byte = w.codes[idx / CODES_PER_BYTE];\n        let shift = (idx % CODES_PER_BYTE) * 2;\n        let code = (byte >> shift) & 0x3;\n        dst[i] = (code as i32 - 1) as f32 * w.scales[idx / GROUP];\n    }\n}\n\npub fn matmul_staged(x: &[f32], w: &PackedWeights, m: usize, n: usize, k: usize) -> Vec<f32> {\n    let mut out = vec![0.0f32; m * n];\n    let tiles = k / TILE;\n    if tiles == 0 {\n        return out;\n    }\n    let mut buf = [[0.0f32; TILE]; 2]; // the B0/B1 staging ring\n    stage_tile(w, &mut buf[0], 0, 0, k);\n    for tile_g in 0..tiles {\n        if tile_g + 1 < tiles {\n            stage_tile(w, &mut buf[(tile_g + 1) % 2], 0, tile_g + 1, k); // lookahead\n        }\n        let tile = &buf[tile_g % 2];\n        for row in 0..m {\n            let mut acc = 0.0f32;\n            for i in 0..TILE {\n                acc += x[row * k + tile_g * TILE + i] * tile[i];\n            }\n            out[row * n] += acc;\n        }\n    }\n    out\n}\n\npub struct PlainStack {\n    pub codes: Vec<u8>,\n    pub scales: Vec<f32>,\n}\n\n// RIDER: gate+up stacked along the output axis ONCE on first use -- the\n// same bytes concatenated into a plain value, never a module parameter.\npub fn stack_gateup(gate: &PackedWeights, up: &PackedWeights) -> PlainStack {\n    let mut codes = Vec::with_capacity(gate.codes.len() + up.codes.len());\n    codes.extend_from_slice(&gate.codes);\n    codes.extend_from_slice(&up.codes);\n    let mut scales = Vec::with_capacity(gate.scales.len() + up.scales.len());\n    scales.extend_from_slice(&gate.scales);\n    scales.extend_from_slice(&up.scales);\n    PlainStack { codes, scales }\n}".to_string(),
        },

        // ── N: the PROOF-side operand elision — a load-time bitwise proof
        // that one epilogue operand is a pure function of another deletes
        // the operand's in-kernel LOAD. The offset-family FIFTH member. ─
        // Source: Hadamard.swift (biasesAreNegativeScales +
        // HadamardConstantLayoutCache) + Qwen35.swift (NarrowEpilogue).
        KernelRule {
            rule_id: "proven-redundant-operand-load-elision".to_string(),
            gpu_concept: "MECHANISM (proof-of-equality load elision): when an epilogue operand is PROVABLY a pure function of another already-loaded operand, PROVE the identity at LOAD time with a bitwise check, CACHE the proof on operand identity, INVALIDATE on parameter update -- and DELETE the operand's in-kernel LOAD. SOURCE-REPORTED (Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d, Hadamard.swift): the narrow epilogue's NEG arm -- 'every offset is the negated scale (FP16 bits proven at load), so `-sv` is the offset's exact FP32 value; no load' (in-kernel bv = -sv); the F32S arm -- 'scalesT holds the FP16 scales widened to FP32 at load (exact), so `sv` is the same value without the conversion' (widen once at load, never per group). THE PROOF: biasesAreNegativeScales -- scales.view(uint16) ^ 0x8000 == biases.view(uint16); the sign-flip is exact FP16 negation INCLUDING signed zero (the source's own fixture arm pins -0.0), so bitwise equality of the flipped bits proves bias == -scale with NO arithmetic at all -- 'proven per constant pair (all 402 pairs of this checkpoint)'. The proof is CACHED in HadamardConstantLayoutCache keyed on array object identity (===) with an explicit clear: 'This cache is cleared by the owning projection on parameter updates' -- staleness is handled by invalidation on ANY parameter write, never by re-proving per forward. PROVENANCE CAVEAT (decision content): first use 263983c (staged8 NEGATIVE_SCALE_BIAS verify arm, b0 = -s0; b1 = -s1) was ERASED by 5029baf -- a TREE REPLACEMENT, not a merge, so blame-based attribution lost it -- restored 4124922, second use cfb35b0 (NarrowEpilogue); a disappeared optimization can be a tree-replacement artifact, not a rejected one. FAMILY (offset/operand-correction, the FIFTH member): B107 integer-mma-span-epilogue-dequant = consumer per-group code-sum lookup; B96 bit-plane-plane-sums-input-side-offset-dot = consumer bit-plane offset dot; B180 deferred-bias-ternary-dp4a-exact-isum = weight-side deferral; B181 signed-activation-codes-drop-dequant-offset-term = writer-side elimination; THIS = PROOF-of-equality -- not a lookup, not a deferral, not an operand encoding: a load-time bitwise proof that removes the load outright. DISTINCT-FROM: factor-affine-quant-scale-out-of-element-loop (folds scales into arithmetic but STILL loads them) and constant-scale-folded-into-upload-copy (B36 -- folds a constant into bytes at upload; the F32S arm is the closest kin, widen at load once, while the NEG arm -- deleting a SECOND operand's load via a cross-operand bitwise proof -- is the novel half). ANTI-REGIME: operands not bitwise-derivable from each other (learned independently, updated on separate schedules with no shared invalidation point); per-token (non-constant) operands; an identity-keyed cache that cannot hook parameter updates -- keep both loads. CITE: Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d -- Vendor/mlx-swift/Source/MLXNN/Hadamard.swift (HadamardConstantLayoutCache.biasesAreNegativeScales) + Qwen35.swift (NarrowEpilogue). Batch 181 / Plan 174 / Research 212.".to_string(),
            ref_shape: "const GROUP: usize = 128;\n\n// Minimal exact FP16 -> FP32 widening (zeros, subnormals, normals,\n// inf/nan) for the fixture.\nfn widen(bits: u16) -> f32 {\n    let sign = ((bits & 0x8000) as u32) << 16;\n    let e = ((bits >> 10) & 0x1f) as u32;\n    let m = (bits & 0x03ff) as u32;\n    if e == 0 && m == 0 {\n        f32::from_bits(sign)\n    } else if e == 0 {\n        let mut mm = m;\n        let mut e32 = 113u32;\n        while mm & 0x0400 == 0 {\n            mm <<= 1;\n            e32 -= 1;\n        }\n        f32::from_bits(sign | (e32 << 23) | ((mm & 0x03ff) << 13))\n    } else if e == 0x1f {\n        f32::from_bits(sign | 0x7f80_0000 | (m << 13))\n    } else {\n        f32::from_bits(sign | ((e + 112) << 23) | (m << 13))\n    }\n}\n\n// NAIVE: the epilogue loads BOTH constant operands per group, even where\n// this checkpoint's biases are byte-identical to the negated scales.\nfn epilogue_naive(codes: &[i8], scales_f16: &[u16], biases_f16: &[u16]) -> Vec<f32> {\n    let mut out = Vec::with_capacity(codes.len() / GROUP);\n    for g in 0..codes.len() / GROUP {\n        let sv = widen(scales_f16[g]); // load 1 + widen per group\n        let bv = widen(biases_f16[g]); // load 2 + widen per group -- provably redundant\n        let base = g * GROUP;\n        let mut c: i32 = 0;\n        for k in 0..GROUP {\n            c += codes[base + k] as i32;\n        }\n        out.push(sv * c as f32 + bv);\n    }\n    out\n}".to_string(),
            opt_pattern: "const GROUP: usize = 128;\n\nfn widen(bits: u16) -> f32 {\n    let sign = ((bits & 0x8000) as u32) << 16;\n    let e = ((bits >> 10) & 0x1f) as u32;\n    let m = (bits & 0x03ff) as u32;\n    if e == 0 && m == 0 {\n        f32::from_bits(sign)\n    } else if e == 0 {\n        let mut mm = m;\n        let mut e32 = 113u32;\n        while mm & 0x0400 == 0 {\n            mm <<= 1;\n            e32 -= 1;\n        }\n        f32::from_bits(sign | (e32 << 23) | ((mm & 0x03ff) << 13))\n    } else if e == 0x1f {\n        f32::from_bits(sign | 0x7f80_0000 | (m << 13))\n    } else {\n        f32::from_bits(sign | ((e + 112) << 23) | (m << 13))\n    }\n}\n\n#[derive(Clone, Copy, PartialEq, Eq)]\nenum EpilogueForm {\n    Base,             // per-group: load + widen scale AND bias\n    NegBias,          // proven bv == -sv: bv = -sv, NO bias load\n    NegBiasF32Scales, // NegBias + scales pre-widened to FP32 once at load\n}\n\n// Load-time proof cache, keyed on operand object identity (address).\nstruct ProofCache {\n    proven: Vec<(usize, bool)>,\n}\n\nimpl ProofCache {\n    fn new() -> Self {\n        ProofCache { proven: Vec::new() }\n    }\n\n    // biasesAreNegativeScales: the sign-flip is exact FP16 negation\n    // INCLUDING signed zero, so scales ^ 0x8000 == biases bitwise (per\n    // constant pair) proves bias == -scale with no arithmetic at all.\n    fn check(&mut self, scales: &[u16], biases: &[u16]) -> bool {\n        let key = scales.as_ptr() as usize;\n        for (k, p) in self.proven.iter() {\n            if *k == key {\n                return *p;\n            }\n        }\n        let ok =\n            scales.len() == biases.len() && scales.iter().zip(biases.iter()).all(|(&s, &b)| s ^ 0x8000 == b);\n        self.proven.push((key, ok));\n        ok\n    }\n\n    // The owning projection clears this on ANY parameter update.\n    fn invalidate(&mut self) {\n        self.proven.clear();\n    }\n}\n\n// OPT: the epilogue takes the PROVEN form and never touches the bias\n// table; F32S additionally reads scales pre-widened at load.\nfn epilogue(\n    codes: &[i8],\n    form: EpilogueForm,\n    scales_f16: &[u16],\n    biases_f16: &[u16],\n    scales_f32: &[f32],\n) -> Vec<f32> {\n    let mut out = Vec::with_capacity(codes.len() / GROUP);\n    for g in 0..codes.len() / GROUP {\n        let (sv, bv) = match form {\n            EpilogueForm::Base => (widen(scales_f16[g]), widen(biases_f16[g])),\n            EpilogueForm::NegBias => {\n                let sv = widen(scales_f16[g]);\n                (sv, -sv) // exact: negation is a sign-bit flip; no bias load\n            }\n            EpilogueForm::NegBiasF32Scales => {\n                let sv = scales_f32[g]; // widened once at load\n                (sv, -sv)\n            }\n        };\n        let base = g * GROUP;\n        let mut c: i32 = 0;\n        for k in 0..GROUP {\n            c += codes[base + k] as i32;\n        }\n        out.push(sv * c as f32 + bv);\n    }\n    out\n}\n\nfn pick_form(scales: &[u16], biases: &[u16], cache: &mut ProofCache, pre_widened: bool) -> EpilogueForm {\n    if cache.check(scales, biases) {\n        if pre_widened {\n            EpilogueForm::NegBiasF32Scales\n        } else {\n            EpilogueForm::NegBias\n        }\n    } else {\n        EpilogueForm::Base // the proof refused: keep both loads\n    }\n}".to_string(),
        },

        // ── D: the THREAD-SHAPE rule — a GPU-wait-heavy engine thread is
        // parked on efficiency cores because its threadgroup looks light;
        // a work-interval deadline hint is the lever that moves it.
        // NotBenchable decision content. ───────────────────────────────
        // Source: CBv2EngineWorkInterval.swift (the 5029baf LEAD-6 file).
        KernelRule {
            rule_id: "engine-work-interval-performance-core-pin".to_string(),
            gpu_concept: "MECHANISM (the THREAD-SHAPE rule -- NotBenchable decision content): a thread whose round is dominated by waiting on a GPU looks light to the OS scheduler and gets parked on efficiency cores, pricing the round's HOST work at E-core clocks. SOURCE-REPORTED (Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d, CBv2EngineWorkInterval.swift, M4 Max per-thread per-performance-level counters, verbatim): 'The thread sleeps on the GPU for most of every round, so its thread group looks light and the scheduler recommends the efficiency cluster for it'; the per-round host work is identical every round ('55 M instructions for the verify build') yet 'the scheduler runs the engine thread on the efficiency cluster (1.0-2.5 GHz, IPC 2.7) instead of a performance core (3.7-4.5 GHz, IPC 4.1). The verify build then takes 11.4 ms instead of 3.8 ms.' Queue QoS does NOT fix it: 'The queue's QoS (userInitiated or userInteractive) does not change that, and a time-constraint policy is silently ignored on a dispatch worker thread' -- SCOPE: DISPATCH WORKER THREADS; a thread the process OWNS (e.g. a spawned pthread / Rust std::thread) may still take THREAD_TIME_CONSTRAINT_POLICY (untested in the source -- a legitimate third arm). FIX: a work interval with a deadline around the round's host work -- 'From the readback to the end of the step, the host work is one interval of the engine's own workgroup, due a few milliseconds after the readback' -- which moves the thread to a performance core: 'the verify build took 3.1 ms in every round, and GPU idle per round fell from 2.0 ms to 0.6 ms with unchanged GPU busy time.' The source resolves the interval creator via dlsym (the framework does not export it) and FAILS OPEN everywhere -- 'Every failure leaves the plain dispatch thread' -- with kill-switch MLXFAST_ENGINE_WORK_INTERVAL=0. REGIME: (a) substantial IDENTICAL per-round host work; (b) the thread sleeps on a device wait most of each round; (c) Apple-silicon scheduling. ANTI-REGIME: CPU-bound threads (the scheduler already places them), short-lived threads, non-Apple platforms. NOTBENCHABLE: the win metric is OS scheduler PLACEMENT -- no Pareto/alloc validator hosts it (the B100/B177 NotBenchable precedent); the quoted numbers are EXPECTATION PRICING, never a benchable code shape. Lane note (a HYPOTHESIS, not a finding): whether OUR decode host-marshal thread matches this shape is unverified -- confirm with an E-vs-P-core placement trace BEFORE offering the three-arm A/B (off / work-interval / time-constraint on our own pthread). CITE: Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d -- Vendor/mlx-swift-lm/Libraries/MLXLMCommon/ContinuousBatchingV2/CBv2EngineWorkInterval.swift. Batch 181 / Plan 174 / Research 212. RIDER (Batch 182, the same delta's post-pin accept wave, delta cfb35b0d..831fae7 -- CBv2EngineWorkInterval.swift L30 + L39-41, verbatim): the mechanism gains THREE refinements -- (1) RENEWAL: a prompt forward's host work outlives one 4 ms deadline ('A prompt forward's host work outlives one deadline: building and encoding'), so the thread drifted back to E-cores mid-step (the seed step's engine CPU ran 94% there); renew (finish + start the next interval) at promptForwardBegan/promptSubmitted -> 59 ms instead of 82 ms; (2) NEW ANTI-REGIME, measured: NEVER start an interval on a thread that joined none -- 'joined no interval is left alone: the timed `prefill` verb's worker thread runs its forward on the performance cluster by itself (13% efficiency), and joining it to an interval of its own moved it there (76%)' -- only threads already inside a joined interval are renewed; (3) the idle-step instance (EngineLoopV2.swift L2350: a step that finalized nothing starts the interval at step begin); kill-switch MLXFAST_PROMPT_WORK_INTERVAL.".to_string(),
            ref_shape: "// Naive: the engine loop submits device work, blocks on the result,\n// then does the identical per-round host marshaling. The thread sleeps\n// on the device most of every round, so its threadgroup looks light and\n// the scheduler parks it on an efficiency core; the round's HOST work\n// then runs at E-core clocks every round.\nuse std::sync::mpsc;\n\nfn submit_device() -> u64 {\n    1 // stub: enqueue the round's device work\n}\n\npub fn run_naive(rounds: usize) -> Vec<u64> {\n    let mut done = Vec::with_capacity(rounds);\n    for _ in 0..rounds {\n        let (tx, rx) = mpsc::channel();\n        let rid = submit_device();\n        std::thread::spawn(move || {\n            tx.send(rid).ok();\n        });\n        let result = rx.recv().unwrap_or(0); // device-wait: mostly sleep here\n        done.push(result.wrapping_mul(0x9E37_79B9_7F4A_7C15));\n    }\n    done\n}".to_string(),
            opt_pattern: "// Optimized: wrap the round's host work (readback to end of step) in\n// a work interval with a deadline, which places the thread on a\n// performance core. Fail-open: new() returns None on ANY failure and\n// the plain thread runs on; kill-switch ENGINE_WORK_INTERVAL=0.\nuse std::sync::mpsc;\n\nfn submit_device() -> u64 {\n    1\n}\n\npub struct WorkInterval {\n    open: bool,\n}\n\nimpl WorkInterval {\n    // Opens the interval with a deadline a few milliseconds out. A real\n    // impl resolves the interval-create symbol dynamically (dlsym in the\n    // source) and fails open on a missing symbol or any OS refusal.\n    pub fn new() -> Option<WorkInterval> {\n        if std::env::var(\"ENGINE_WORK_INTERVAL\").ok().as_deref() == Some(\"0\") {\n            return None; // kill-switch: leave the plain thread\n        }\n        Some(WorkInterval { open: true })\n    }\n}\n\nimpl Drop for WorkInterval {\n    fn drop(&mut self) {\n        self.open = false; // close the interval: the round's work is due/done\n    }\n}\n\npub fn run_intervals(rounds: usize) -> Vec<u64> {\n    let mut done = Vec::with_capacity(rounds);\n    for _ in 0..rounds {\n        let _interval = WorkInterval::new(); // covers this round's host work\n        let (tx, rx) = mpsc::channel();\n        let rid = submit_device();\n        std::thread::spawn(move || {\n            tx.send(rid).ok();\n        });\n        let result = rx.recv().unwrap_or(0);\n        done.push(result.wrapping_mul(0x9E37_79B9_7F4A_7C15));\n    }\n    done\n}".to_string(),
        },

        // ── D: budget the in-flight CAP so independent host work overlaps
        // device work — submit the leading K layers, build the dependent
        // state under their GPU time, submit the rest after. ───────────
        // Source: EngineLoopV2+MTPFinalize.swift (the split-submission
        // block; DARKBLOOM_DFLASH2_DRAFT_LEAD_LAYERS).
        KernelRule {
            rule_id: "split-submission-in-flight-cap-overlap".to_string(),
            gpu_concept: "MECHANISM: budget the submission against the queue's in-flight cap so independent host work OVERLAPS device work instead of serializing behind it. SOURCE-REPORTED (Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d, EngineLoopV2+MTPFinalize.swift, verbatim): 'One asyncEval of the whole proposal holds this thread in MLX's in-flight cap (at most 10 command buffers; the proposal is ~30) until the drafter is nearly done, and only then does the host build and encode the committed recurrent state below, eating the drafter tail the next verify build needs to hide under. So the drafter hands the GPU only its leading layers while it builds, the committed state is built and submitted while they run, and the rest of the proposal is submitted after it, still inside this finalize.' Lead sizing: 'Three layers (with the context projection they read) are ~11 of the proposal's ~32 command buffers on an M4 Max: as many as MLX keeps in flight without holding the host, and enough GPU time to cover the committed state's host build.' The lead is env-tunable (DARKBLOOM_DFLASH2_DRAFT_LEAD_LAYERS; 0 restores one submission, a positive count overrides). RIDER (early-binding, same source): absorbContext -- 'A layer's context keys and values depend on the context alone (the block reads them through attention), so they can enter the cache before the block's anchor is known' -- the block forward carries zero context rows; pipeline-INDEPENDENCE lets work start before a shared dependency resolves (the same family as the split itself). REGIME: an encoder whose submission would exceed the device/queue in-flight cap (any bounded-depth submission queue) PLUS independent host work that can be built WHILE the leading part runs. ANTI-REGIME: cap headroom (submit all at once); the host work depends on the leading part's RESULTS (a true dependency, not overlap); consumers needing the whole proposal before any part runs. DISTINCT-FROM: chain-dispatches-single-sync-point (B19 -- sync PLACEMENT: one sync after N dispatches vs N syncs; THIS budgets the in-flight CAP so independent host work overlaps device work -- a different axis; compose). CITE: Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d -- Vendor/mlx-swift-lm/Libraries/MLXLMCommon/ContinuousBatchingV2/MTP/EngineLoopV2+MTPFinalize.swift. Batch 181 / Plan 174 / Research 212. RIDER (Batch 182, the same delta's post-pin accept wave, delta cfb35b0d..831fae7): `CBv2MTPDraftBeforeReadback` is this rule's next instance with two new contracts -- (a) the budget arithmetic now runs against a 10-CB cap with 2 leading layers ~= 9 in flight (MTPContractsV2.swift L509: 'enough to stay within MLX's 10 in-flight buffers (2: ~9 on an M4 Max).'); (b) the ADOPT-OR-DROP CONTRACT: the speculative block is built before readback from device values and adopted ONLY on the exact outcome the early-block path would have produced ('confirmed == accepted + 1', fixed depth, budget guard -- EngineLoopV2+MTPFinalize.swift L140: 'into the drafter; adopted below, or dropped. The budget guard keeps'); any other outcome DROPS it and the ordinary path runs; plus the interaction: prompt-quoted rows are excluded from draft-before-readback speculation (the prompt-continuation-draft-override B182 rule's half). RIDER (Batch 276, the DECODE-STEP BUILD-CHUNK face, Layr-Labs/mlxfast-qwen38-125b-a6b-engine @ 59160bd (MIT), intro commit f70c17d -- where this host (sourced from the sibling mlxfast-bonsai2-27b engine) hands the GPU leading layers while the host builds under the in-flight cap, this face adds the qwen38 engine's per-step cadence law: the decode step is BUILD-bound -- 'The measured decode step on this family is bound by graph construction and' 'launch count, not by weight bandwidth (see docs and the fork's' 'Qwen4ExpDecodeStepCostTests), so the lever is fewer, heavier launches.' (TrackFastModel.swift:13-15) -- so the partially-built graph dispatches every asyncChunk layers while the CPU keeps building ('Layers per partial dispatch inside a forward (0 = one dispatch per step).' :307; the dispatch site: 'Dispatch the graph so far: the GPU starts on these layers while the' 'CPU keeps building the rest (the build is otherwise GPU-idle time).' :1250-1251). The measured cadence: chunk 12 measured -0.41% vs 3 -- the mid-challenge comment on asyncChunk added at ddf36f3 ('12 measured -0.41% so the gradient favours smaller') and removed at 44d3ba3. The first chunk boundary is SYNC-RELATIVE: 'the first dispatch lands right after the PLE layer, whose host row' 'gather is the one host sync of the step.' -- asyncFirst = 2 (:312-315) -- the first build-chunk boundary sits right AFTER the step's one host sync, not at layer 0 (the asyncFirst boundary landed at 750c51e). Note: the commit-WATERMARK raise/restore lever on this host family already rides phase-scoped-command-buffer-commit-cap-raise (gpu_121, B275) -- not repeated here). Batch 276 / Plan 280 / Research 314.".to_string(),
            ref_shape: "// Naive: submit the WHOLE proposal, then build the committed state.\n// The bounded in-flight queue (capacity 10) stalls the submitter once\n// the cap is hit, so the host only builds the committed state after the\n// proposal is nearly drained -- eating GPU idle the next round needed\n// to hide under.\npub struct QueueCap {\n    pub capacity: usize,\n    pub submitted: usize,\n}\n\nimpl QueueCap {\n    pub fn new() -> Self {\n        QueueCap { capacity: 10, submitted: 0 }\n    }\n\n    pub fn submit(&mut self, n: usize) {\n        while self.submitted + n > self.capacity {\n            self.submitted -= 1; // the device drains; the submitter stalls here\n        }\n        self.submitted += n;\n    }\n\n    pub fn drain(&mut self) {\n        self.submitted = 0;\n    }\n}\n\npub struct Proposal {\n    pub layers: Vec<u64>,\n}\n\npub fn build_committed_state(p: &Proposal) -> u64 {\n    p.layers.iter().fold(0u64, |a, b| a.wrapping_add(*b))\n}\n\npub fn run_naive(q: &mut QueueCap, p: &Proposal) -> u64 {\n    for _ in &p.layers {\n        q.submit(1);\n    }\n    let committed = build_committed_state(p); // host work only AFTER the full submit\n    q.submit(1);\n    q.drain();\n    committed\n}".to_string(),
            opt_pattern: "// Optimized: submit the leading K layers, build+submit the committed\n// state WHILE they run, then submit the rest -- all still inside this\n// finalize. DARKBLOOM_DFLASH2_DRAFT_LEAD_LAYERS: 0 restores one\n// submission; a positive count overrides the default lead.\npub const DEFAULT_LEAD: usize = 3;\n\npub struct QueueCap {\n    pub capacity: usize,\n    pub submitted: usize,\n}\n\nimpl QueueCap {\n    pub fn new() -> Self {\n        QueueCap { capacity: 10, submitted: 0 }\n    }\n\n    pub fn submit(&mut self, n: usize) {\n        while self.submitted + n > self.capacity {\n            self.submitted -= 1; // the device drains under the running lead\n        }\n        self.submitted += n;\n    }\n\n    pub fn drain(&mut self) {\n        self.submitted = 0;\n    }\n}\n\npub struct Proposal {\n    pub layers: Vec<u64>,\n}\n\npub fn build_committed_state(p: &Proposal) -> u64 {\n    p.layers.iter().fold(0u64, |a, b| a.wrapping_add(*b))\n}\n\npub fn lead_layers(total: usize) -> usize {\n    match std::env::var(\"DARKBLOOM_DFLASH2_DRAFT_LEAD_LAYERS\")\n        .ok()\n        .and_then(|v| v.parse::<usize>().ok())\n    {\n        Some(0) => total, // one submission: no split\n        Some(n) => n.min(total),\n        None => DEFAULT_LEAD.min(total),\n    }\n}\n\npub fn run_split(q: &mut QueueCap, p: &Proposal) -> u64 {\n    let lead = lead_layers(p.layers.len());\n    for _ in p.layers.iter().take(lead) {\n        q.submit(1); // the lead runs on the device while the host works below\n    }\n    let committed = build_committed_state(p); // overlapped independent host work\n    q.submit(1);\n    for _ in p.layers.iter().skip(lead) {\n        q.submit(1); // the rest of the proposal, still inside this finalize\n    }\n    q.drain();\n    committed\n}".to_string(),
        },
    ]
}
